const findMiVoice=()=>{if(!('speechSynthesis' in window))return null; const voices=speechSynthesis.getVoices(); return voices.find(v=>/^mi(-|_)?/i.test(v.lang))||voices.find(v=>/Māori|Maori/i.test(v.name))||null};
function speak(text){if(!('speechSynthesis' in window))return {ok:false}; const voice=findMiVoice(); if(!voice)return {ok:false}; speechSynthesis.cancel(); const u=new SpeechSynthesisUtterance(text);u.voice=voice;u.lang=voice.lang;u.rate=.78;u.pitch=1;speechSynthesis.speak(u);return {ok:true}}
function AudioButton({text,large=false,onTextAnswer,immersion=false}){const [native,setNative]=useState(true);const [textShown,setTextShown]=useState(false);useEffect(()=>{const check=()=>setNative(!!findMiVoice());check();if('speechSynthesis'in window){speechSynthesis.onvoiceschanged=check;return()=>speechSynthesis.onvoiceschanged=null}},[]);const reveal=()=>{if(onTextAnswer){onTextAnswer();return}setTextShown(v=>!v)};const play=()=>{const r=speak(text);if(!r.ok){if(onTextAnswer)onTextAnswer();else setTextShown(true)}};return <div className="audio-wrap"><div className="audio-controls"><button className={`audio-btn ${large?'large':''}`} onClick={play} title={native?'Play Māori audio':'Māori audio is unavailable'} aria-label={native?'Play Māori audio':'Māori audio unavailable'}><Volume2 size={large?28:18}/></button>{onTextAnswer&&<button className="audio-fallback" onClick={reveal}>{immersion?'Pānuihia te tuhinga':'Change audio to text'}</button>}{!onTextAnswer&&textShown&&<button className="audio-fallback" onClick={reveal}>{immersion?'Huna te tuhinga':'Hide text'}</button>}</div>{!onTextAnswer&&textShown&&<div className="audio-text-answer">{text}</div>}{!native&&<small className="audio-note">{immersion?'Kāore he reo Māori oro i tēnei pūrere.':'Native Māori audio is not available on this device.'}</small>}</div>}
function makeActivities(level,minutes,topics,progress={},focus='general'){
 const rank=LEVELS.find(x=>x.id===level).rank;
 let pool=learnerItems().filter(i=>i.level<=rank&&(topics.length?topics.includes(i.topic):true));
 if(pool.length<4) pool=learnerItems().filter(i=>i.level<=rank);
 const count=minutes===2?6:minutes===5?10:16;
 const modes=focus==='build'?['listen','order','build','build','speak','choose','translate','cloze']:focus==='bilingual'?['listen','choose','translate','order','build','speak','choose','translate']:focus==='structured'?['listen','order','build','speak','choose','build','speak','cloze']:focus==='kupu'?['listen','choose','match','translate','cloze','speak']:focus==='phrases'?['listen','choose','order','build','speak','translate']:focus==='sentence'?['listen','order','build','build','speak','transform']:['listen','choose','order','build','speak','translate','grammar','match','transform','cloze','dictation','listenOrder'];
 const weighted=[...pool].sort((a,b)=>((progress[a.id]?.score||0)-(progress[b.id]?.score||0))||((progress[a.id]?.last||0)-(progress[b.id]?.last||0)));
 const queue=[...weighted,...pool,...pool];
 return Array.from({length:count},(_,n)=>({type:modes[n%modes.length],item:queue[n%queue.length],key:`${queue[n%queue.length].id}-${modes[n%modes.length]}-${n}`}));
}

const masteryScore=(progress,id)=>progress[id]?.score||0;
const adaptiveWeight=(item,progress)=>{
 const p=progress[item.id];
 if(!p) return 100;
 const score=p.score||0;
 const age=p.last?Math.max(0,(Date.now()-p.last)/86400000):30;
 const streak=p.streak||0;
 return (score<4?80:score<8?45:10) + Math.min(age*4,40) - Math.min(streak*3,15);
};
const buildAdaptiveLesson=(lesson,progress)=>{
 const items=lesson.items.map(id=>ITEMS.find(x=>x.id===id)).filter(Boolean);
 return [...items].sort((a,b)=>adaptiveWeight(b,progress)-adaptiveWeight(a,progress));
};
const adaptiveNextAction=(level,progress)=>{
 const rank=LEVELS.find(x=>x.id===level).rank;
 const visible=learnerItems().filter(i=>i.level<=rank);
 const due=visible.filter(i=>!progress[i.id] || (progress[i.id]?.score||0)<4 || (progress[i.id]?.last&&Date.now()-progress[i.id].last>3*86400000));
 return [...due].sort((a,b)=>adaptiveWeight(b,progress)-adaptiveWeight(a,progress))[0] || visible.sort((a,b)=>adaptiveWeight(b,progress)-adaptiveWeight(a,progress))[0];
};

function dailyReview(level,progress){const rank=LEVELS.find(x=>x.id===level).rank;return learnerItems().filter(i=>i.level<=rank&&progress[i.id]).sort((a,b)=>(progress[a.id]?.score||0)-(progress[b.id]?.score||0)).slice(0,6)}

