function StreakCard(){const g=readGoals();const done=(g.dailyMinutes||0)>=(g.dailyTarget||5);return <section className="streak-card"><div className="streak-number">{g.streak||0}</div><div><p className="eyebrow">CURRENT STREAK</p><h2>{done?'Goal met today':'Keep your reo moving.'}</h2><p>{g.dailyMinutes||0}/{g.dailyTarget||5} minutes today · {g.xp||0} XP</p></div></section>}

